async ({ workspace: { read }, fd: { news } }) => {
  const call = JSON.parse((await read(`/tmp/nvda/call.json`, { format: "raw" })).content);
  const [a, b] = await Promise.allSettled([news({ ticker: "NVDA", limit: 10 }), news({ ticker: "NVDA", start_date: "2026-11-01", limit: 10 })]);
  const fmt = (r: any) => r.status === "fulfilled" ? { url: r.value.url, items: r.value.data.map((x: any) => [x.date, x.title, x.source, x.url]) } : String(r.reason).slice(0, 300);
  const hits: any[] = [];
