    s.forEach((x: string, j: number) => { if (/70%|70 percent|fiscal (year )?28|1 trillion|\$1 trillion|100%/i.test(x)) hits.push([i, t.speakerName, (s[j - 1] || "").slice(0, 250), x.slice(0, 350)]); });
  });
